pub type Counter = {
  current: Int;
  step: Int;
  limit: Int;
}

impl Iterator for Counter {
  type Item = Int;

  fn next(self: &mut Counter) -> Option[Int] {
    if self.current >= self.limit { return None(); }
    let value = self.current;
    self.current = self.current + self.step;
    return Some(value);
  }
}

fn main() -> Int {
  let mut c = Counter{ current: 0, step: 2, limit: 10 };
  var sum = 0;
  sum = sum + c.next().unwrap();  // 0
  sum = sum + c.next().unwrap();  // 2
  sum = sum + c.next().unwrap();  // 4
  return sum;
}
